<?php
require_once __DIR__.'/B19MultiFamilyMariaDbPipelineTest.php';
use App\Application\MarketData\Services\MarketDataEvidenceExportService;
use App\Infrastructure\Persistence\MarketData\EodCorrectionRepository;
use Illuminate\Support\Facades\DB;
use Tests\Support\R0025SyntheticV2World;

/** Same independent fixture setup, one actual world; no repeated historical mutation family. */
class B19ExecutedAdmissionMariaDbProofTest extends B19MultiFamilyMariaDbPipelineTest
{
    private $admissionDirs=[];
    private $admissionResponse;
    private $httpStatus=200;
    protected function identityWorld(): array {$this->admissionResponse=file_get_contents(R0025SyntheticV2World::packagePath().'/inputs/provider_response.json');return R0025SyntheticV2World::build(['http_fetcher'=>function(){return ['status'=>$this->httpStatus,'body'=>$this->admissionResponse,'headers'=>['Content-Type: application/json']];}]);}
    protected function continueIdentityScope(): bool {return false;}
    protected function tearDown(): void {foreach($this->admissionDirs as $d){foreach(glob($d.'/*') as $f)if(is_file($f))unlink($f);rmdir($d);}parent::tearDown();}
    private function exported($type,$id,$date,$name): array {$d=sys_get_temp_dir().'/b19_admission_world_'.uniqid();$this->admissionDirs[]=$d;$s=app(MarketDataEvidenceExportService::class);if($type==='run')$s->exportRunEvidence($id,$d);elseif($type==='correction')$s->exportCorrectionEvidence($id,$d);else$s->exportReplayEvidence($id,$date,$d);$file=$type==='run'?'evidence_pack.json':($type==='correction'?'correction_evidence.json':'replay_evidence_pack.json');$p=json_decode(file_get_contents($d.'/'.$file),true);if(getenv('B19_ADMISSION_CAPTURE'))foreach(glob($d.'/*') as $f)copy($f,base_path('storage/app/market-data/evidence/MD-B19-A001/'.(getenv('B19_ADMISSION_CAPTURE_PREFIX') ?: 'E025_').$name.'_'.basename($f)));return [$p,$d];}
    protected function afterIdentityRun($v,$runId,$fixture,$pubId,$date,array $expected,array $manifest,array $files,array $world,$replay): void {
        $primary=DB::table('eod_runs')->where('run_id',$runId)->first();$pub=DB::table('eod_publications')->where('publication_id',$pubId)->first();$events=DB::table('eod_run_events')->where('run_id',$runId)->get()->map(function($x){return (array)$x;})->all();[$normal]=$this->exported('run',$runId,$date,'normal');$this->assertSame('ADMITTED_COMPLETE',$normal['evidence_admission']['evidence_admission_state']);
        try{DB::table('eod_run_events')->where('run_id',$runId)->delete();[$bad]=$this->exported('run',$runId,$date,'missing_trail');$this->assertSame('ADMITTED_INCOMPLETE',$bad['evidence_admission']['evidence_admission_state']);$this->assertSame('INCOMPLETE',$bad['evidence_completeness']['evidence_completeness_state'],'final completeness cannot claim COMPLETE when mandatory execution trail is unavailable');$this->assertContains('run_event_summary',$bad['run_summary']['evidence_missing_sections']);}finally{DB::table('eod_run_events')->insert($events);}
        $sourceHash=hash_file('sha256',base_path('app/Application/MarketData/Services/MarketDataEvidenceExportService.php'));$this->assertSame($sourceHash,$normal['evidence_admission']['criteria']['exporter_sha256']);$this->assertSame((int)$primary->run_id,$normal['evidence_admission']['selector_id']);$this->assertSame($primary->finished_at,$normal['evidence_admission']['evidence_created_at']);$this->assertFalse($normal['evidence_admission']['claims']['output_correctness']);
        [$match]=$this->exported('replay',$replay,$date,'match');$this->assertSame('PASS',$match['replay_result']['replay_status']);$this->assertSame('ADMITTED_COMPLETE',$match['evidence_admission']['evidence_admission_state']);$this->assertSame($sourceHash,$match['evidence_admission']['criteria']['exporter_sha256']);
        // An independently specified conflicting expectation makes FAIL while its diagnostic evidence remains complete.
        $probe=$expected;$probe['expected_artifact_context']['eligibility_batch_hash']=hash('sha256','independent admission-only mismatch expectation');file_put_contents($fixture.'/expected/expected_replay_result.json',json_encode($probe));$manifest['fixture_version']='b19-admission-mismatch-v1';foreach($manifest['files'] as $f)$manifest['files_sha256'][$f]=hash_file('sha256',$fixture.'/'.$f);file_put_contents($fixture.'/manifest.json',json_encode($manifest));$different=$v->verifyRunAgainstFixture($runId,$fixture,null,$pubId);[$mismatch]=$this->exported('replay',$different['replay_id'],$date,'mismatch');$this->assertSame('MISMATCH',$mismatch['replay_result']['comparison_result']);$this->assertSame('FAIL',$mismatch['replay_result']['replay_status']);$this->assertSame('ADMITTED_COMPLETE',$mismatch['evidence_admission']['evidence_admission_state']);$this->assertFalse($mismatch['evidence_admission']['claims']['output_correctness']);$this->assertNotSame($probe['expected_artifact_context']['eligibility_batch_hash'],$mismatch['actual_state']['eligibility_batch_hash']);
        $repo=new EodCorrectionRepository();$c=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent admission close106 correction','requester',$pubId,$runId);$repo->approve($c->correction_id,'approver');$body=json_decode($this->admissionResponse,true);$body['chart']['result'][0]['indicators']['quote'][0]['close'][0]=106;$this->admissionResponse=json_encode($body);$changed=$world['pipeline']->runDaily($date,'api',$c->correction_id);[$correction]=$this->exported('correction',$c->correction_id,$date,'correction');$this->assertSame('ADMITTED_COMPLETE',$correction['evidence_admission']['evidence_admission_state']);$this->assertTrue($correction['publication_switch']);$this->assertSame($pubId,$correction['prior_publication']['publication_id']);$this->assertSame($runId,$correction['prior_run_id']);$this->assertSame((int)$changed->run_id,$correction['new_run_id']);$this->assertSame($pub->bars_batch_hash,$correction['old_hashes']['bars_batch_hash']);$this->assertSame(106.0,(float)DB::table('eod_bars_history')->where('publication_id',$correction['new_publication']['publication_id'])->value('close'));
        [$historical]=$this->exported('run',$runId,$date,'historical');$this->assertSame('ADMITTED_COMPLETE',$historical['evidence_admission']['evidence_admission_state']);$this->assertFalse($historical['publication_context']['is_current_publication']);$this->assertNotSame($pubId,(int)$historical['pointer_context']['raw_pointer_context']['publication_id']);
        $this->httpStatus=401;try{$world['pipeline']->runDaily('2026-03-20','api');$this->fail('actual auth error must propagate');}catch(\App\Infrastructure\MarketData\Source\SourceAcquisitionException $error){$this->assertSame('RUN_SOURCE_AUTH_ERROR',$error->reasonCode());}$failed=DB::table('eod_runs')->where('trade_date_requested','2026-03-20')->orderBy('run_id','desc')->first();[$failure]=$this->exported('run',$failed->run_id,'2026-03-20','failed');$this->assertSame('FAILED',$failure['run_summary']['terminal_status']);$this->assertSame('ADMITTED_INCOMPLETE',$failure['evidence_admission']['evidence_admission_state']);$this->assertSame('INCOMPLETE',$failure['evidence_completeness']['evidence_completeness_state']);
        if(getenv('B19_ADMISSION_CAPTURE'))file_put_contents(base_path('storage/app/market-data/evidence/MD-B19-A001/'.(getenv('B19_ADMISSION_CAPTURE_PREFIX') ?: 'E025_').'authoritative_inputs.json'),json_encode(['baseline_run_before_export'=>$primary,'baseline_publication_before_export'=>$pub,'event_trail_before_export'=>$events,'config_snapshot'=>DB::table('md_config_snapshots')->where('config_snapshot_id',$pub->config_snapshot_id)->first(),'changed_correction_primary'=>DB::table('eod_dataset_corrections')->where('correction_id',$c->correction_id)->first(),'failed_run'=>$failed,'declared_expected_before_replay'=>$expected,'mismatch_expectation'=>$probe],JSON_PRETTY_PRINT));
    }
}
